#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Cell { material: u8, moisture: u8 }
#[derive(Clone, Copy)]
struct Edit { index: usize, before: Cell, after: Cell }
fn undo(world: &mut [Cell], edits: &[Edit]) -> (usize, usize) {
    let mut restored = 0;
    let mut skipped = 0;
    for edit in edits.iter().rev() {
        match world.get_mut(edit.index) {
            Some(live) if *live == edit.after => {
                *live = edit.before;
                restored += 1;
            }
            _ => skipped += 1,
        }
    }
    (restored, skipped)
}
fn main() {
    let air = Cell { material: 0, moisture: 0 };
    let wood = Cell { material: 1, moisture: 0 };
    let wet_wood = Cell { material: 1, moisture: 50 };
    let mut world = [wood, wet_wood];
    let edits = [Edit { index: 0, before: air, after: wood },
                 Edit { index: 1, before: air, after: wood }];
    assert_eq!(undo(&mut world, &edits), (1, 1));
    assert_eq!(world, [air, wet_wood]);
    println!("restored 1; skipped 1 changed cell");
}

#[derive(Debug, PartialEq)]
struct Gains { wind: f32, rain: f32, fire: f32 }
fn gains(wind: f32, rain: f32, burning: usize,
         muted: bool, event_duck: f32) -> Gains {
    let master = if muted { 0.0 } else { 1.0 };
    let bed = master * event_duck.clamp(0.0, 1.0);
    Gains {
        wind: wind.clamp(0.0, 1.0) * 0.15 * bed,
        rain: rain.clamp(0.0, 1.0) * 0.35 * bed,
        fire: (burning as f32 / 200.0).clamp(0.0, 1.0) * 0.30 * bed,
    }
}
fn main() {
    let quiet = gains(0.4, 0.0, 0, false, 1.0);
    let fire = gains(0.4, 0.0, 5000, false, 1.0);
    assert!(quiet.fire == 0.0 && fire.fire <= 0.30);
    assert_eq!(gains(1.0, 1.0, 200, true, 1.0),
               Gains { wind: 0.0, rain: 0.0, fire: 0.0 });
    println!("bounded fire; immediate mute; independent world state");
}

fn fit(window_w: u32, window_h: u32, budget: u64) -> (u32, u32) {
    if window_w < 4 || window_h < 4 { return (0, 0); }
    let max_w = window_w / 4;
    let max_h = window_h / 4;
    let ratio = window_h as f64 / window_w as f64;
    let mut best = (0, 0);
    for w in 1..=max_w {
        let h = ((w as f64 * ratio).round() as u32).clamp(1, max_h);
        let active = u64::from(w + 32) * u64::from(h + 32);
        if active <= budget && u64::from(w)*u64::from(h) >
            u64::from(best.0)*u64::from(best.1) { best = (w, h); }
    }
    best
}
fn main() {
    assert_eq!(fit(1280, 720, 74_624), (320, 180));
    let (w,h) = fit(1920,1080,74_624);
    assert_eq!((w,h),(320,180));
    assert!(u64::from(w+32)*u64::from(h+32) <= 74_624);
    println!("1920x1080 window: {}x{} physical world pixels",w*4,h*4);
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct Event { at_ms: u64, action: &'static str }
fn crossed(events: &[Event], before: u64, now: u64) -> Vec<Event> {
    events.iter().copied().filter(|e| before < e.at_ms && e.at_ms <= now).collect()
}
fn main() {
    let events = [Event { at_ms: 8_000, action: "rain fixture begins" },
        Event { at_ms: 18_000, action: "clear fixture resumes" },
        Event { at_ms: 28_000, action: "ignite dry exposed grass" },
        Event { at_ms: 36_000, action: "rain suppresses the fire" }];
    assert_eq!(crossed(&events, 7_900, 8_100).len(), 1);
    assert!(crossed(&events, 8_100, 8_200).is_empty());
    for event in crossed(&events, 0, 60_000) {
        println!("{:>2}s  {}", event.at_ms / 1000, event.action);
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Kind { Air, Sand, Stone }
fn wind_right(row: &mut [Kind]) {
    let mut moved = vec![false; row.len()];
    for x in 0..row.len().saturating_sub(1) {
        if !moved[x] && row[x] == Kind::Sand && row[x+1] == Kind::Air {
            row.swap(x, x+1);
            moved[x+1] = true;
        }
    }
}
fn main() {
    let mut row = [Kind::Sand, Kind::Air, Kind::Air, Kind::Stone];
    wind_right(&mut row);
    assert_eq!(row, [Kind::Air, Kind::Sand, Kind::Air, Kind::Stone]);
    assert_eq!(row.iter().filter(|k| **k == Kind::Sand).count(), 1);
    println!("one tick: one eligible grain, one bounded move");
}

fn next_eruption(seed: u64, feature: u64, now: u64) -> Option<u64> {
    const PERIOD: u64 = 72_000;
    let offset = (seed ^ feature.wrapping_mul(0x9E3779B97F4A7C15)) % PERIOD;
    let start = (now / PERIOD).checked_mul(PERIOD)?;
    let candidate = start.checked_add(offset)?;
    if candidate > now { Some(candidate) }
    else { candidate.checked_add(PERIOD) }
}
fn main() {
    let seed = 17;
    let id = 42;
    let first = next_eruption(seed,id,0).unwrap();
    let after_absence = next_eruption(seed,id,72_000 * 10).unwrap();
    assert!(after_absence > 72_000 * 10);
    assert_eq!(next_eruption(seed,id,0),Some(first));
    assert_eq!(next_eruption(seed,id,first),first.checked_add(72_000));
    println!("one stable schedule; no historical eruption queue");
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Kind { Air, Water, Sand, Stone }
fn erode(cells: &mut [Kind], width: usize, from: usize, to: usize) -> bool {
    if width == 0 || from >= cells.len() || to >= cells.len() { return false; }
    let (x,y)=(from%width,from/width);
    let (tx,ty)=(to%width,to/width);
    if cells[from]!=Kind::Sand || cells[to]!=Kind::Air || ty!=y+1 || x.abs_diff(tx)>1 {
        return false;
    }
    let wet = (x>0 && cells[from-1]==Kind::Water)
        || (x+1<width && from+1<cells.len() && cells[from+1]==Kind::Water);
    if !wet { return false; }
    cells.swap(from,to);
    true
}
fn main() {
    let mut cells=[Kind::Air,Kind::Air,Kind::Air,
        Kind::Stone,Kind::Sand,Kind::Water,
        Kind::Stone,Kind::Air,Kind::Stone];
    let before=cells.iter().filter(|k|**k==Kind::Water).count();
    assert!(erode(&mut cells,3,4,7));
    assert_eq!(cells[4],Kind::Air);
    assert_eq!(cells[7],Kind::Sand);
    assert_eq!(cells.iter().filter(|k|**k==Kind::Water).count(),before);
    println!("sand moved downhill; water count unchanged");
}

use std::collections::{BTreeSet, VecDeque};
#[derive(Default)]
struct Pending { order: VecDeque<u32>, keys: BTreeSet<u32> }
impl Pending {
    fn request(&mut self, id: u32) {
        if self.keys.insert(id) { self.order.push_back(id); }
    }
    fn batch(&mut self, limit: usize) -> Vec<u32> {
        let mut out=Vec::new();
        while out.len()<limit {
            let Some(id)=self.order.pop_front() else { break; };
            self.keys.remove(&id);
            out.push(id);
        }
        out
    }
}
fn main() {
    let mut q=Pending::default();
    for _ in 0..1000 { q.request(7); }
    q.request(8); q.request(9);
    assert_eq!(q.order.len(),3);
    assert_eq!(q.batch(2),vec![7,8]);
    assert_eq!(q.batch(2),vec![9]);
    println!("1002 requests became 3 unique pending jobs");
}

#[derive(Clone, Copy)]
enum Source { Player, Nature }
#[derive(Clone, Copy)]
enum Command { Rain { column: i32 } }
fn accept(command: Command, source: Source, now: u64,
          ready: &mut u64, applied: &mut Vec<i32>) -> bool {
    if matches!(source,Source::Player) && now<*ready { return false; }
    match command { Command::Rain { column } => applied.push(column) }
    if matches!(source,Source::Player) { *ready=now.saturating_add(24_000); }
    true
}
fn main() {
    let (mut ready,mut applied)=(0,Vec::new());
    assert!(accept(Command::Rain{column:2},Source::Player,0,&mut ready,&mut applied));
    assert!(!accept(Command::Rain{column:2},Source::Player,1,&mut ready,&mut applied));
    assert!(accept(Command::Rain{column:3},Source::Nature,1,&mut ready,&mut applied));
    assert_eq!(applied,vec![2,3]);
    println!("shared effect path; distinct scheduling policies");
}

use std::{fmt, fs, io, path::{Path, PathBuf}};
#[derive(Debug)]
enum ConfigError {
    Read { path: PathBuf, source: io::Error },
    Invalid { path: PathBuf, message: String },
}
impl fmt::Display for ConfigError {
    fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result {
        match self {
            Self::Read{path,source}=>write!(f,"read {}: {}",path.display(),source),
            Self::Invalid{path,message}=>write!(f,"decode {}: {}",path.display(),message),
        }
    }
}
impl std::error::Error for ConfigError {
    fn source(&self)->Option<&(dyn std::error::Error+'static)> {
        match self { Self::Read{source,..}=>Some(source), _=>None }
    }
}
fn parse_budget(text:&str,path:&Path)->Result<u32,ConfigError> {
    text.trim().parse::<u32>().ok().filter(|n|*n>0)
        .ok_or_else(||ConfigError::Invalid{path:path.to_owned(),
            message:"expected a positive active-cell budget".to_owned()})
}
fn load_budget(path:&Path)->Result<u32,ConfigError> {
    let text=fs::read_to_string(path)
        .map_err(|source|ConfigError::Read{path:path.to_owned(),source})?;
    parse_budget(&text,path)
}
fn main() {
    let path=Path::new("settings.txt");
    assert_eq!(parse_budget("74624",path).unwrap(),74_624);
    let error=parse_budget("zero",path).unwrap_err();
    println!("{error}");
    let _loader:fn(&Path)->Result<u32,ConfigError>=load_budget;
}

type HeightFn=fn(i32)->i32;
fn height_v1(x:i32)->i32 { 20+x.rem_euclid(4) }
fn height_v2(x:i32)->i32 { 30+x.rem_euclid(7) }
fn generator(version:u16)->Result<HeightFn,String> {
    match version {
        1=>Ok(height_v1),
        2=>Ok(height_v2),
        _=>Err(format!("unsupported generator version {version}")),
    }
}
fn validate_format(version:u16)->Result<(),String> {
    if version==1 { Ok(()) }
    else { Err(format!("unsupported save format {version}")) }
}
fn main() {
    validate_format(1).unwrap();
    let old=generator(1).unwrap();
    let latest=generator(2).unwrap();
    assert_eq!(old(5),21);
    assert_eq!(latest(5),35);
    assert!(generator(99).is_err());
    println!("format 1 remains readable; generator 1 still returns 21");
}

use std::path::{Path,PathBuf};
fn asset_root(executable:&Path,mac_bundle:bool)->Result<PathBuf,String> {
    let parent=executable.parent().ok_or("executable has no parent")?;
    if mac_bundle {
        let contents=parent.parent().ok_or("missing Contents directory")?;
        Ok(contents.join("Resources").join("assets"))
    } else { Ok(parent.join("assets")) }
}
fn main() {
    let flat=asset_root(Path::new("dist/rusty-linux/game"),false).unwrap();
    let app=asset_root(Path::new("dist/Rusty.app/Contents/MacOS/game"),true).unwrap();
    assert_eq!(flat,PathBuf::from("dist/rusty-linux/assets"));
    assert_eq!(app,PathBuf::from("dist/Rusty.app/Contents/Resources/assets"));
    println!("flat: {}",flat.display());
    println!("app: {}",app.display());
}

struct Gate { name: &'static str, passed: bool }
fn ready(gates:&[Gate])->Result<(),Vec<&'static str>> {
    let failures:Vec<_>=gates.iter().filter(|g|!g.passed).map(|g|g.name).collect();
    if failures.is_empty() { Ok(()) } else { Err(failures) }
}
fn main() {
    let gates=[Gate{name:"headless regression",passed:true},
        Gate{name:"floor-machine frame times",passed:false},
        Gate{name:"native package smoke tests",passed:true},
        Gate{name:"complete-save recovery",passed:true}];
    match ready(&gates) {
        Ok(())=>println!("candidate ready for explicit publication review"),
        Err(missing)=>println!("release blocked: {}",missing.join(", ")),
    }
}
